            "type": "integer",
            "description": "Optional credibility signal — an adoption and liveness signal: how often `resource` was exercised (dashboard views, query executions, page reads) over `usage_window`. For a single artifact it is that artifact's own exercise count; for a scope descriptor it is the number of exercises within the scope that touch the concept. Coarse by design: comparable at the alive-versus-dead and order-of-magnitude level and against a source's own history, but not a precise cross-kind ranking. Read as liveness and trend, not as a score. OKF v0.2 §5.1."
          },
          "last_modified": {
            "type": "string",
            "format": "date-time",
            "description": "Optional credibility signal — a recency signal: when the source itself last changed, as an ISO 8601 datetime with an explicit UTC offset (`2026-06-15T00:00:00Z`). Distinct from `generated.at`, which records when the concept was written. OKF v0.2 §5, §5.1."
          },
          "usage_window": {
            "type": "object",
            "description": "Optional per-entry override of the `usage_window` written as a sibling of `sources`. OKF v0.2 §5.1.",
            "properties": {
              "from": {
                "type": "string",
                "format": "date-time",
                "description": "Start of the window framing this entry's `usage_count`, as an ISO 8601 datetime with an explicit UTC offset (`2026-06-01T00:00:00Z`). OKF v0.2 §5, §5.1."
              },
              "to": {
                "type": "string",
                "format": "date-time",
                "description": "End of the window framing this entry's `usage_count`, as an ISO 8601 datetime with an explicit UTC offset (`2026-06-30T00:00:00Z`). OKF v0.2 §5, §5.1."
              }
            }
          }
        }
      }
    },
    "usage_window": {
      "type": "object",
      "description": "Written once as a sibling of `sources`, this frames every `usage_count` in the list with a `{ from, to }` range. A single entry may carry its own `usage_window` to override it. OKF v0.2 §5, §5.1.",
      "properties": {
        "from": {
          "type": "string",
          "format": "date-time",
          "description": "Start of the shared usage window, as an ISO 8601 datetime with an explicit UTC offset (`2026-06-01T00:00:00Z`). OKF v0.2 §5, §5.1."
        },
        "to": {
          "type": "string",
          "format": "date-time",
          "description": "End of the shared usage window, as an ISO 8601 datetime with an explicit UTC offset (`2026-06-30T00:00:00Z`). OKF v0.2 §5, §5.1."
        }
      }
    },
    "generated": {
      "type": "object",
      "required": [
        "by"
      ],
      "description": "How the current content was produced. Kept distinct from `verified` because who wrote a concept need not be who confirmed it. OKF v0.2 §5.2.",
      "properties": {
        "by": {
          "type": "string",
          "description": "REQUIRED within `generated`. An actor in the OKF convention: `<producer>/<version>` for agents and tools (`reference_agent/gemini-2.5-pro`), `human:<id>` for a person (`human:ahormati`), or `process:<id>` for an automated process (`process:finance-nightly`). Consumers that classify trust key off the `human:` prefix, so producers MUST use it for hand-authored or human-confirmed content — a rule about which form to pick for which content, which frontmatter alone cannot check, so the three forms are documented here rather than enforced by a pattern. OKF v0.2 §5.2, §7."
        },
        "at": {
          "type": "string",
          "format": "date-time",
          "description": "An ISO 8601 datetime with an explicit UTC offset (`2026-06-30T14:00:00Z`) marking the content's last meaningful change. Consumers use it to tell a recent edit from a stale fact. Supersedes v0.1's top-level `timestamp`. OKF v0.2 §5, §5.2, §13.1."
        }
      }
    },
    "verified": {
      "description": "Who or what has confirmed the content against its sources or `resource` — a list of verification events. Multiple entries capture independent checks, for example a human sign-off plus a nightly process; \"how recently\" is the latest `at`. Independent of `generated.at`: content can change without re-confirmation, and facts can be re-confirmed without regeneration. A single verifier MAY be written as one bare `{ by, at }` mapping without the list dash, and consumers MUST treat that as a one-element list — hence the two accepted shapes here. Absence means unverified, which is a valid state, never a rejection. OKF v0.2 §5.2, §5.3, §11.",
      "anyOf": [
        {
          "type": "object",
          "description": "The bare single-verifier mapping form. OKF v0.2 §5.2.",
          "properties": {
            "by": {
              "type": "string",
              "description": "The verifying actor: `<producer>/<version>`, `human:<id>`, or `process:<id>`. A `human:` verifier is what raises the trust tier to human-reviewed; non-human verifiers alone yield machine-confirmed. OKF v0.2 §5.2, §5.3, §7."
            },
            "at": {
              "type": "string",
              "format": "date-time",
              "description": "An ISO 8601 datetime with an explicit UTC offset (`2026-07-01T09:00:00Z`) recording when the verification event happened. OKF v0.2 §5, §5.2."
            }
          }
        },
        {
          "type": "array",
          "description": "The list form: one entry per independent verification event. OKF v0.2 §5.2.",
          "items": {
            "type": "object",
            "properties": {
              "by": {
                "type": "string",
                "description": "The verifying actor: `<producer>/<version>`, `human:<id>`, or `process:<id>`. A `human:` verifier is what raises the trust tier to human-reviewed; non-human verifiers alone yield machine-confirmed. OKF v0.2 §5.2, §5.3, §7."
              },
              "at": {
                "type": "string",
                "format": "date-time",
                "description": "An ISO 8601 datetime with an explicit UTC offset (`2026-07-01T09:00:00Z`) recording when the verification event happened. OKF v0.2 §5, §5.2."
              }
            }
          }
        }
      ]
    },
    "status": {
      "enum": [
        "draft",
        "stable",
        "deprecated"
      ],
      "description": "Lifecycle state. `draft` = not yet reviewed, possibly incomplete. `stable` = ready for consumption. `deprecated` = kept for links and history, no longer current. Absent means `stable`, so the key is only worth writing to say draft or deprecated. These three values are the whole set OKF defines, which is why this is the pack's only enum. OKF v0.2 §5.4."
    },
    "stale_after": {
      "type": "string",
      "format": "date-time",
      "description": "An absolute instant, an ISO 8601 datetime with an explicit UTC offset (`2026-12-31T00:00:00Z`): the concept is stale when `now >= stale_after`. Absolute rather than a relative TTL so staleness stays a plain comparison with no reference to when the concept was read. An instant in the past is a freshness signal for consumers, not a violation. OKF v0.2 §5, §5.5, §10.5."
    }
  }
}
